class FuelTank:
    def __init__(self, capacity, fuel=0):
        self.capacity = capacity
        self.fuel = fuel

    def fill(self, amount):
        space = self.capacity - self.fuel
        added = min(amount, space)
        self.fuel += added
        print("Added", added, "litres")

    def use(self, amount):
        if amount > self.fuel:
            print("Not enough fuel! Only", self.fuel, "litres left")
        else:
            self.fuel -= amount
            print("Used", amount, "litres")

    def level(self):
        return self.fuel

