import math

class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return 0

    def describe(self):
        print(self.name, "mold, area", round(self.area(), 2))

class Circle(Shape):
    def __init__(self, radius):
        super().__init__("Circle")
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

class Square(Shape):
    def __init__(self, side):
        super().__init__("Square")
        self.side = side

    def area(self):
        return self.side ** 2

for mold in [Circle(3), Square(4)]:
    mold.describe()

class Worker:
    def __init__(self, name, hourly_rate):
        self.name = name
        self.hourly_rate = hourly_rate

    def pay(self, hours):
        return self.hourly_rate * hours

    def report(self, hours):
        print(self.name, "earns", self.pay(hours), "ration tokens")

class Foreman(Worker):
    def __init__(self, name, hourly_rate, bonus):
        super().__init__(name, hourly_rate)
        self.bonus = bonus

    def pay(self, hours):
        return super().pay(hours) + self.bonus

