import sys

def power(a, b):
    print("power(" + str(a) + ", " + str(b) + ") called")
    if b == 0:
        return 1
    return a * power(a, b - 1)

print("Result:", power(3, 4))
print("Python's recursion limit:", sys.getrecursionlimit())

def nested_sum(items):
    total = 0
    for item in items:
        if isinstance(item, list):
            total += nested_sum(item)
        else:
            total += item
    return total

print(nested_sum([1, 2, [3, 4], [5, 6]]))
print(nested_sum([1, [2, [3, [4, [5]]]]]))

def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

for n in range(10):
    print(fib(n), end=" ")
print()
print("fib(20) =", fib(20))

maze = ["Z", ["-", "Z", ["Z", "-"]], "-", [["Z"], "-"]]

def count_zombies(room):
    count = 0
    for spot in room:
        if isinstance(spot, list):
            count += count_zombies(spot)
        elif spot == "Z":
            count += 1
    return count

def deepest(room):
    deepest_inside = 0
    for spot in room:
        if isinstance(spot, list):
            deepest_inside = max(deepest_inside, deepest(spot))
    return 1 + deepest_inside

def show(room, depth=0):
    for spot in room:
        if isinstance(spot, list):
            print("  " * depth + "door")
            show(spot, depth + 1)
        else:
            print("  " * depth + spot)

print("Zombies in the maze:", count_zombies(maze))
print("Levels deep:", deepest(maze))
show(maze)

def sequential_search(rooms, target):
    position = 0
    while position < len(rooms):
        if rooms[position] == target:
            return True, position
        position += 1
    return False, -1

rooms = [11, 23, 58, 31, 56, 77, 43, 12, 65, 19]
print("Room 31:", sequential_search(rooms, 31))
print("Room 40:", sequential_search(rooms, 40))

def search(items, target, low, high):
    if low > high:
        print("  range empty -> not found")
        return False
    mid = (low + high) // 2
    print("  low", low, "mid", mid, "high", high, "-> checking", items[mid])
    if items[mid] == target:
        return True
    if items[mid] < target:
        return search(items, target, mid + 1, high)
    return search(items, target, low, mid - 1)

doses = [0, 1, 3, 8, 14, 18, 19, 34, 52]
for target in [3, 17]:
