    print("Found:", search(doses, target, 0, len(doses) - 1))

def find_bed(beds, target):
    low = 0
    high = len(beds) - 1
    while low <= high:
        mid = (low + high) // 2
        if beds[mid] == target:
            return mid
        elif beds[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

beds = [3, 8, 12, 17, 21, 26, 30, 35]
print("Bed 26 is at index", find_bed(beds, 26))
