def bubble_sort(items):
    n = len(items)
    for p in range(n - 1):
        swapped = False
        for i in range(n - 1 - p):
            if items[i] > items[i + 1]:
                items[i], items[i + 1] = items[i + 1], items[i]
                swapped = True
        print("Pass", p + 1, items)
        if not swapped:
            break
    return items

bubble_sort([14, 46, 43, 27, 57, 41, 45, 21, 70])

patients = [("Ana", 3), ("Bo", 8), ("Cy", 1), ("Di", 6), ("Ed", 9), ("Fay", 4)]

def selection_sort(items):
    for i in range(len(items)):
        smallest = i
        for j in range(i + 1, len(items)):
            if items[j][1] < items[smallest][1]:
                smallest = j
        items[i], items[smallest] = items[smallest], items[i]
    return items

def find_name(items, name):
    for i in range(len(items)):
        if items[i][0] == name:
            return i
    return -1

def has_severity(items, score):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid][1] == score:
            return True
        elif items[mid][1] < score:
            low = mid + 1
        else:
            high = mid - 1
    return False

