queue = ward[::-1]

order = []
for name, severity in queue:
    order.append(name + " (" + str(severity) + ")")
print("Treatment order:", ", ".join(order))
print("Di is number", find_name(queue, "Di") + 1, "in the queue")
print("Anyone at severity 9?", has_severity(ward, 9))
